#' @title basic_summaries Result Class
#' @description S7 class for `basic_summaries()` output.
#' @param tbl_gt A `gt_tbl` object created from the summary table.
#' @param raw_table A `gtsummary` table object before gt conversion.
#' @param figures A named list of ggplot figures generated by variable.
#' @returns An S7 class object.
basic_summaries_result <- S7::new_class(
  name = "basic_summaries_result",
  properties = list(
    tbl_gt = S7::class_any,
    raw_table = S7::class_any,
    figures = S7::class_list
  ),
  validator = function(self) {
    if (!inherits(self@tbl_gt, "gt_tbl")) {
      "@tbl_gt must inherit from 'gt_tbl'"
    } else if (!inherits(self@raw_table, "gtsummary")) {
      "@raw_table must inherit from 'gtsummary'"
    } else if (is.null(names(self@figures))) {
      "@figures must be a named list"
    }
  }
)

#' @title Constructor for basic_summaries Result
#' @param tbl_gt A `gt_tbl` object created from the summary table.
#' @param raw_table A `gtsummary` table object before gt conversion.
#' @param figures A named list of ggplot figures generated by variable.
#' @returns A `basic_summaries_result` S7 object.
new_basic_summaries_result <- function(tbl_gt, raw_table, figures) {
  basic_summaries_result(
    tbl_gt = tbl_gt,
    raw_table = raw_table,
    figures = figures
  )
}

#' @title Print basic_summaries Result
#' @param x A `basic_summaries_result` object.
#' @param ... Additional arguments passed to `print()`.
#' @rdname basic_summaries
#' @export
print.basic_summaries_result <- function(x, ...) {
  print(S7::prop(x, "tbl_gt"), ...)
  invisible(x)
}

S7::method(print, basic_summaries_result) <- function(x, ...) {
  print.basic_summaries_result(x, ...)
}
